import { defineConfig } from 'vite'
import tailwindcss from '@tailwindcss/vite'
import { readdirSync, statSync, existsSync } from 'node:fs'
import { resolve, join } from 'node:path'

// GitHub Pages project site: https://ab-s0lution.github.io/Le-C---Salon-de-Coiffure-Rennes/
// Multi-page build: every folder that holds an index.html is an entry (generated by scripts/gen-pages.mjs).
const root = __dirname
function findPages(dir: string, out: Record<string, string> = {}, rel = ''): Record<string, string> {
  for (const name of readdirSync(dir)) {
    if (['node_modules', 'dist', '.git', '.github', 'src', 'public', 'scripts'].includes(name)) continue
    const p = join(dir, name)
    if (statSync(p).isDirectory()) findPages(p, out, rel ? `${rel}/${name}` : name)
  }
  if (existsSync(join(dir, 'index.html'))) out[rel || 'index'] = resolve(dir, 'index.html')
  return out
}

export default defineConfig({
  base: '/Le-C---Salon-de-Coiffure-Rennes/',
  plugins: [tailwindcss()],
  build: {
    rollupOptions: { input: findPages(root) },
  },
})
